def longest_increasing_subsequence(nums):
    if not nums:
        return 0

    max_length = 1
    dp_table = [1] * len(nums)

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp_table[i] = max(dp_table[i], dp_table[j] + 1)
                max_length = max(max_length, dp_table[i])

    return max_length
