def count_decodings(s):
    n = len(s)

    # dp[i] represents the number of ways s[:i+1] can be decoded.
    dp = [0] * (n + 1)
    dp[0], dp[1] = 1, 1 if s and s[0] != '0' else 0

    for i in range(2, n + 1):
        # If the current digit is not '0', it can be a single letter.
        if s[i - 1] != '0':
            dp[i] += dp[i - 1]

        # If the two digits together form a number between 10 and 26, it can be decoded as a double letter.
        if int(s[i - 2:i]) >= 10 and int(s[i - 2:i]) <= 26:
            dp[i] += dp[i - 2]

    return dp[n]

