def wrap_text(text, width):
    lines = []
    while text:
        if len(text) <= width:
            lines.append(text)
            break
        else:
            index = text.rfind(' ', 0, width)
            if index == -1:
                lines.append(text[:width])
                text = ''
            else:
                lines.append(text[:index].strip())
                text = text[index:].strip()
    return lines
```

