def sliding_window_max(nums, k):
    if len(nums) < k:
        raise ValueError("Window size cannot be greater than the array length")

    maxes = []
    start = 0

    for end in range(len(nums)):
        while start <= end and nums[start] <= nums[end]:
            start += 1
        maxes.append(nums[start])

        if end - start + 1 < k:
            continue

        maxes.pop(0)

    return maxes
```

