from itertools import groupby

def compress_ranges(nums):
    # Group the numbers by whether they increase, decrease, or stay constant
    groups = ((k, len(list(g))) for k, g in groupby(nums))

    # Process each group to determine if it should be represented as a range
    result = []
    for k, n in groups:
        if n >= 3:
            result.append(f"{k}->{k + n - 1}")
        else:
            result.extend(map(str, range(k, k + n)))

    # Return the result list sorted in ascending order
    return sorted(result)
```

