def next_permutation(nums):
    pivot = -1

    # Find the rightmost index where nums[i] < nums[i+1]
    for i in range(len(nums) - 2, -1, -1):
        if nums[i] < nums[i + 1]:
            pivot = i
            break

    if pivot == -1:
        # If no such element exists, reverse the list to get the smallest possible lexicographical order
        nums.reverse()
        return nums

    # Find the smallest number in nums[pivot+1:] that is greater than nums[pivot]
    for j in range(len(nums) - 1, pivot, -1):
        if nums[j] > nums[pivot]:
            break

    # Swap nums[pivot] and nums[j]
    nums[pivot], nums[j] = nums[j], nums[pivot]

    # Reverse the sublist from nums[pivot+1:]
    nums[pivot + 1:] = reversed(nums[pivot + 1:])

    return nums

