def lru_results(capacity, operations):
    cache = {}
    recent_keys = []

    for op in operations:
        action, key, value = op

        if action == 'put':
            if key in cache:
                del cache[key]  # Remove the old entry for the same key
            else:
                if len(cache) >= capacity:
                    oldest_key = recent_keys.pop(0)
                    del cache[oldest_key]

            cache[key] = value
            recent_keys.append(key)

        elif action == 'get':
            if key in cache:
                recent_keys.remove(key)
                recent_keys.append(key)
                return cache[key]
            else:
                return -1
```

