def compress_ranges(nums):
    if not nums:
        return []

    def stringify(start, end):
        if start == end:
            return str(start)
        else:
            return f"{start}->{end}"

    res = []
    i = 0

    while i < len(nums):
        j = i + 1
        current_num = nums[i]

        # Find the end of the run of three or more consecutive integers
        while j < len(nums) and nums[j] == current_num + 1:
            j += 1

        # Add the start of the run to the result list
        res.append(stringify(current_num, nums[j - 1]))

        i = j

    return res
