def lru_results(capacity, operations):
    cache = {}
    recent = []

    def get(key):
        if key in cache:
            recent.remove(key)
            recent.append(key)
            return cache[key]
        else:
            return -1

    for op, *args in operations:
        if op == 'put':
            if len(cache) < capacity:
                cache[args[0]] = args[1]
                recent.append(args[0])
            else:
                key_to_remove = recent.pop(0)
                del cache[key_to_remove]
                cache[args[0]] = args[1]
                recent.append(args[0])
        elif op == 'get':
            return get(*args)
    return [get(key) for key in range(capacity)]
