def count_decodings(s):
    n = len(s)
    if not n:
        return 0

    # DP array where dp[i] stores the number of ways to decode s[:i]
    dp = [0] * (n + 1)
    dp[0], dp[1] = 1, 1 if s[0] != '0' else 0

    for i in range(2, n + 1):
        # If the current digit can be decoded alone
        if s[i - 1] != '0':
            dp[i] += dp[i - 1]

        # If the two digits together can be decoded as a number between 1 and 26
        if 10 <= int(s[i - 2:i]) <= 26:
            dp[i] += dp[i - 2]

    return dp[n]

def min_coins(amount, coins):
    # Initialize a list to store the minimum coins needed for each amount from 0 to the given amount
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0  # Base case: zero coins are needed to make amount 0

    # Iterate through each coin
    for coin in coins:
        # Update the minimum coins needed for each amount from the current coin value onwards
        for i in range(coin, amount + 1):
