def next_permutation(nums):
    # Find the first position from right where numbers stop decreasing
    i = len(nums) - 2
    while i >= 0 and nums[i] >= nums[i + 1]:
        i -= 1

    # If no such position is found, reverse the array to get the smallest permutation
    if i < 0:
