def next_permutation(nums):
    if len(nums) <= 1:
        return nums

    # Traverse the array from right to left to find the first element that is smaller than its predecessor.
    i = len(nums) - 2
    while i >= 0 and nums[i] >= nums[i + 1]:
        i -= 1

    if i == -1:
        return sorted(nums)

    # Find the smallest element greater than nums[i] to the right of i.
    j = len(nums) - 1
    while nums[j] <= nums[i]:
        j -= 1

    # Swap nums[i] and nums[j].
    nums[i], nums[j] = nums[j], nums[i]

    # Reverse the array from i+1 to the end.
    nums[i + 1:] = reversed(nums[i + 1:])

    return nums
