def split_escaped(text):
    result = []
    i = 0
    while i < len(text):
        if text[i] == '\\':
            # Skip one character for escaping
            i += 1
            if i == len(text):
                result.append('')
                break
        elif text[i].isspace():
            # Skip spaces in the middle of an escaped string
            i = text.find(' ', i)
        else:
            # Collect characters until we hit another delimiter
            end = text.find(',', i)
            if end == -1:
                end = len(text)
            result.append(text[i:end])
            i = end

    return result
