def shortest_path_length(n, edges, source, target):
    def bfs(start):
        queue = [start]
        visited = set([start])
        distance = {start: 0}

        while queue:
            current = queue.pop(0)
            if current == target:
                return distance[current], len(distance)

            for neighbor, weight in edges[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
                    distance[neighbor] = distance[current] + weight

        return -1, None
