def longest_palindrome(s):
    def expand_around_center(left, right):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return right - left - 1

    max_length = 0
    start_index = 0

    for i in range(len(s)):
        # Odd length palindrome
        odd_length = expand_around_center(i, i)
        if odd_length > max_length:
            max_length = odd_length
            start_index = i - (max_length // 2)

        # Even length palindrome
        even_length = expand_around_center(i, i + 1)
        if even_length > max_length:
            max_length = even_length
            start_index = i - (max_length // 2) + 1

    return s[start_index:start_index + max_length]

