def sliding_window_max(nums, k):
    # Use a deque to store indices that form windows of size k.
    max_indices = deque()

    for i, num in enumerate(nums):
        # Remove indices from the front if they are out of the current window.
        while max_indices and nums[max_indices[0]] <= num:
            max_indices.popleft()

        # Add the current index to the back.
        max_indices.append(i)

        # If we have reached a full window, remove the leftmost index from the deque.
        if i >= k - 1:
            result.append(nums[max_indices[0]])
            # Remove indices from the front if they are no longer within the window.
            while max_indices and max_indices[0] <= i - k + 1:
