def count_coin_combinations(amount, coins):
    def dp(i, remaining_amount):
        if remaining_amount == 0:
            return 1
        if i >= len(coins) or remaining_amount < 0:
            return 0

        # Count with this coin and skip it
        ways_with_coin = dp(i + 1, remaining_amount - coins[i])

        # Skip this coin and count without it
        ways_without_coin = dp(i + 1, remaining_amount)

        return ways_with_coin + ways_without_coin

    return dp(0, amount)

