def wrap_text(text, width):
    # Split text into words
    words = text.split()

    # If no words, return []
    if not words:
        return []

    lines = []
    current_line = ""

    for word in words:
        # Add space at the end of current line if not empty and the word is longer than width
        if current_line and len(current_line) + 1 + len(word) > width:
            lines.append(current_line)
            current_line = word
        else:
            # Otherwise, add word to current line
            current_line += " " + word

    # Add the last line if not empty
    if current_line:
        lines.append(current_line)

    return lines

