def count_decodings(s):
    n = len(s)
    if not n:
        return 0

    # DP array where dp[i] stores the number of ways to decode s[:i]
    dp = [0] * (n + 1)
    dp[0], dp[1] = 1, 1  # Base cases: empty string and one character

    for i in range(2, n + 1):
        # Check if the current character is non-zero
        if s[i - 1] != '0':
            dp[i] += dp[i - 1]

        # Check if the two characters together form a valid number between 10 and 26
        if i >= 2 and '10' <= s[i - 2:i] <= '26':
            dp[i] += dp[i - 2]

    return dp[n]

