def shortest_path_length(n, edges, source, target):
    adj = [[] for _ in range(n)]

    # Build adjacency list
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))

    # Find distance from all nodes to the target using BFS
    dist = [-1] * n
    queue = [(source, 0)]

    while queue:
        node, d = queue.pop(0)

        if node == target:
            return d

        for neighbor, weight in adj[node]:
            if dist[neighbor] == -1:
                dist[neighbor] = d + weight
                queue.append((neighbor, d + weight))

    # If target is unreachable, return -1
    return -1

