def evaluate_expression(s):
    def precedence(op):
        # Define the precedence of operations
        return {'+': 1, '-': 1, '*': 2, '/': 2, '(': 3}

    def apply_operator(operators, values):
        while operators and operators[-1] != '(':
            op = operators.pop()
            b = values.pop()
            a = values.pop()
            if op == '+':
                values.append(a + b)
            elif op == '-':
                values.append(a - b)
            elif op == '*':
                values.append(a * b)
            elif op == '/':
                values.append(int(a / b))  # Truncate toward zero

    def parse_expression(s):
        operators = []
        values = []
        i = 0
        while i < len(s):
            if s[i] == ' ':
                i += 1
            elif s[i] in {'+', '-', '*', '/'}:
                op = s[i]
                while operators and precedence(operators[-1]) >= precedence(op):
                    apply_operator(operators, values)
                operators.append(op)
                i += 1
            elif s[i] == '(':
                operators.append(s[i])
                i += 1
            elif s[i].isdigit():
                num = ''
                while i < len(s) and s[i].isdigit():
                    num += s[i]
                    i += 1
                values.append(int(num))
        while operators:
            apply_operator(operators, values)
        return values[0]

    # Remove spaces and split the expression into tokens
    tokens = filter(None, s.replace(' ', ''))
    return parse_expression(tokens)
