    stack = []
    current_number = ''
    sign = 1

    for char in s:
        if char.isdigit():
            current_number += char
        elif char == '(':
            stack.append((sign, current_number))
            current_number = ''
            sign = 1
        elif char == ')':
            prev_sign, prev_number = stack.pop()
            result = prev_sign * int(prev_number) + int(current_number)
            if len(stack) > 0:
