def min_coins(amount, coins):
    # Initialize a list to store the minimum coins needed for each amount from 0 to the given amount
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0  # Base case: zero coins needed to make an amount of 0

    # Iterate through each possible amount up to the given amount
    for i in range(1, amount + 1):
        # For each coin denomination, check if it can be used to make the current amount
        for coin in coins:
            # If the coin value is less than or equal to the current amount, update the dp array
            if i >= coin:
                dp[i] = min(dp[i], dp[i - coin] + 1)

    return dp[amount] if dp[amount] != float('inf') else -1

