def next_permutation(nums):
    index = -1

    # Find the last decreasing element from right to left
    for i in range(len(nums)-2, -1, -1):
        if nums[i] < nums[i+1]:
            index = i
            break

    # If no such element is found, the array is already sorted in descending order
    if index == -1:
        return nums[::-1]

    # Find the smallest element greater than nums[index]
    for i in range(len(nums)-1, index, -1):
        if nums[i] > nums[index]:
            break

    # Swap the found elements
    nums[index], nums[i] = nums[i], nums[index]

    # Reverse the array after the index
    nums[index+1:] = nums[index+1:][::-1]
