def count_islands(grid):
    def dfs(i, j, row, col):
        if i < 0 or i >= row or j < 0 or j >= col or grid[i][j] != '1':
            return
        grid[i][j] = '0'  # Mark the cell as visited
        dfs(i + 1, j, row, col)  # Explore down
        dfs(i - 1, j, row, col)  # Explore up
        dfs(i, j + 1, row, col)  # Explore right
        dfs(i, j - 1, row, col)  # Explore left

    if not grid or not grid[0]:
        return 0

    row, col = len(grid), len(grid[0])
    count = 0

    for i in range(row):
        for j in range(col):
            if grid[i][j] == '1':
                dfs(i, j, row, col)
                count += 1

    return count
