from collections import defaultdict

def compress_ranges(nums):
    if not nums:
        return []

    nums.sort()
    ranges = defaultdict(list)
    start = None

    for num in nums:
        if start is None:
            start = num
        elif num == start + 1:
            continue
        else:
            ranges[start].append(start)
            start = num

    if start is not None:
        ranges[start].append(start)

    result = []
    for key, value in ranges.items():
        if len(value) >= 3:
            result.append(f"{value[0]}->{value[-1]}")
        else:
            result.extend(map(str, value))

    return sorted(result)

# Example usage:
nums = [2, 3, 4, 5, 6, 7, 8, 9]
print(compress_ranges(nums))  # Output: ['2->9']
```

In this solution, we use a `defaultdict` to group consecutive numbers into ranges. We iterate through the sorted list of numbers and collect runs. For runs with three or more consecutive numbers, we format them as 'start->end'. For shorter runs, we simply convert them to strings. The result is sorted before being returned.

