def evaluate_expression(s):
    def parse_number():
        i = 0
        while i < len(s) and s[i].isdigit():
            i += 1
        return int(s[:i])

    def parse_unary_minus():
        if s[0] == '-':
            return -parse_number()
        return parse_number()

    def parse_operator precedence(op):
        if op in ('*', '/'):
            return 2
        elif op in ('+', '-'):
            return 1
        else:
            raise ValueError("Invalid operator")

    def parse_expression():
        i = 0
        while i < len(s) and s[i] != ')':
            if s[i].isdigit() or s[i] == '(':
                num = parse_number()
                if s[i] in ('+', '-', '*'):
                    next_op = s[i]
                elif s[i] == '(':
                    next_expr = parse_expression()
                i += 1
