                    next_num = parse_number()
                    if precedence == 2:
                        return num * next_num
                    elif precedence == 1:
                        return num - next_num
                else:
                    if precedence == 2:
                        return num // next_num
                    elif precedence == 1:
                        return num + next_num
        return parse_unary_minus()

    return parse_expression()
