def count_coin_combinations(amount, coins):
    # Initialize a list to hold the number of combinations for each amount from 0 to amount
    combinations = [0] * (amount + 1)
    combinations[0] = 1  # There is exactly one way to make change for 0 using no coins

    # Iterate through each coin and update the combinations array
    for coin in coins:
        for i in range(coin, amount + 1):
            combinations[i] += combinations[i - coin]

    return combinations[amount]

