def next_permutation(nums):
    pivot = -1

    # Find the rightmost index where nums[i] < nums[i+1]
    for i in range(len(nums) - 2, -1, -1):
        if nums[i] < nums[i + 1]:
            pivot = i
            break

    if pivot == -1:
        # If no such element is found, the array is already sorted in reverse order.
        return nums.reverse()

    # Find the smallest number greater than nums[pivot] to its right
    for j in range(len(nums) - 1, pivot, -1):
        if nums[j] > nums[pivot]:
            break

    # Swap nums[pivot] and nums[j]
    nums[pivot], nums[j] = nums[j], nums[pivot]

    # Sort the elements to the right of nums[pivot]
    nums[pivot + 1:] = sorted(nums[pivot + 1:])
