def count_decodings(s):
    n = len(s)
    if not n:
        return 0

    # DP array where dp[i] stores the number of ways to decode s[:i]
    dp = [0] * (n + 1)
    dp[0], dp[1] = 1, 1 if s[0] != '0' else 0

    for i in range(2, n + 1):
        # Check the current digit alone
        if s[i - 1] != '0':
            dp[i] += dp[i - 1]

        # Check the current and previous digits together
        two_digit = int(s[i - 2:i])
        if two_digit >= 10 and two_digit <= 26:
            dp[i] += dp[i - 2]

    return dp[n]

