def evaluate_expression(s):
    def precedence(op):
        # Define the precedence of operations
        return {'+': 1, '-': 1, '*': 2, '/': 2, '(': 3}

    def apply_op(a, b, op):
        # Apply the operator to two operands
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return int(a / b)

    def parse_expression(expr):
        tokens = expr.split()
        stack = []
        for token in tokens:
            if token.isdigit():
                stack.append(int(token))
            elif token in precedence:
                while stack and stack[-1] != '(' and precedence[token] <= precedence[stack[-1]]:
                    op = stack.pop()
                    b = stack.pop()
                    a = stack.pop()
                    result = apply_op(a, b, op)
