        if node == target:
            return current_weight

        for neighbor, weight in adj[node]:
            new_weight = current_weight + weight
            if new_weight < dist[neighbor][node]:
                dist[neighbor][node] = new_weight
                heapq.heappush(pq, (new_weight, neighbor))

