def topological_order(n, edges):
    # Build adjacency list for the graph
    adj_list = [[] for _ in range(n)]
    indegree = [0] * n

    for u, v in edges:
        adj_list[u].append(v)
        indegree[v] += 1

    # Topological sort using BFS with Kahn's algorithm
    queue = []
    for i in range(n):
        if indegree[i] == 0:
            queue.append(i)

    result = []
    while queue:
        u = queue.pop(0)
        result.append(u)

        for v in adj_list[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)

    # Check if the graph has a cycle
    return result if all(indegree[i] == 0 for i in range(n)) else []

