def spiral_order(matrix):
    if not matrix:
        return []

    result = []
    top, bottom, left, right = 0, len(matrix) - 1, 0, len(matrix[0]) - 1

    while top <= bottom and left <= right:
        # Traverse from left to right
        for i in range(left, right + 1):
            result.append(matrix[top][i])
        top += 1

        # Traverse downwards
        for i in range(top, bottom + 1):
            result.append(matrix[i][right])
        right -= 1

        # Check if there is a left boundary and traverse from right to left
        if top <= bottom:
            for i in range(right, left - 1, -1):
                result.append(matrix[bottom][i])
            bottom -= 1

        # Check if there is a top boundary and traverse from bottom to up
        if left <= right:
            for i in range(bottom, top - 1, -1):
                result.append(matrix[i][left])
            left += 1

    return result

def wrap_text(text, width):
    words = text.split()

    if not words:
        return []

    lines = []
    current_line = ''

    for word in words:
        # Check if adding the current word to the line exceeds the width
        if len(current_line) + len(word) > width:
            # If so, start a new line
            if current_line:
                lines.append(current_line)
            current_line = word
        else:
            # Otherwise, add the word to the current line with a space if it's not the first word
            if current_line:
                current_line += ' '
            current_line += word

    # Add any remaining words on their own line
    if current_line:
        lines.append(current_line)

    return lines

