def edit_distance(a, b):
    m, n = len(a), len(b)

    # Create a 2D array to store the results of subproblems
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the dp array
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j  # Insertions required to turn a into b
            elif j == 0:
                dp[i][j] = i  # Deletions required to turn a into b
            elif a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # No operation needed
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])

    return dp[m][n]

